        buffer += token
        if any(token.endswith(ending) for ending in sentence_endings):
            yield buffer.strip()
            buffer = ""
    if buffer.strip():
        yield buffer


def find_last_punctuation(buffer: str):
    indices = [buffer.rfind(ending) for ending in SENTENCE_ENDINGS]
    return indices and max(indices)


